import logging
import uuid


logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        self.stock = stock

    def place_order(
        self, user: str, item: str, quantity: int, is_admin: bool = False
    ) -> tuple[int, str]:
        try:
            reservation_id = self.stock.reserve(item, quantity)
            return 200, f"Order confirmed. Reservation ID: {reservation_id}"
        except Exception as exc:
            reference = uuid.uuid4().hex
            logger.exception("Unexpected order error. Reference: %s", reference)

            message = f"Sorry, your order could not be completed. Reference: {reference}"
            if is_admin:
                message += f" ({type(exc).__name__}: {exc})"
            return 500, message
